using System.Net;using System.Security.Cryptography;using System.Text;using BARANG.Core.Domain.Catalog;using BARANG.Core.Domain.Organization;using BARANG.Core.Domain.Security;using BARANG.Core.Infrastructure.Persistence;using Microsoft.EntityFrameworkCore;using Xunit;
namespace BARANG.Core.IntegrationTests.Database;
[Collection(PostgreSqlDatabaseFixture.CollectionName)]public sealed class PublicClientApiContractTests(PostgreSqlDatabaseFixture database)
{
 [Fact]public async Task ApiClientScopeCompanyCatalogAndProblemContractAreEnforced(){CancellationToken ct=TestContext.Current.CancellationToken;await database.ResetAsync(ct);Guid company=Guid.NewGuid(),other=Guid.NewGuid(),clientId=Guid.NewGuid();string secret="phase20-api-client-secret-123456789";await using(CoreDbContext db=database.CreateAdministrationCoreDbContext()){db.Companies.AddRange(Company.Create(company,"CLIENT_A","Client A",DateTimeOffset.UtcNow).Value,Company.Create(other,"CLIENT_B","Client B",DateTimeOffset.UtcNow).Value);db.Products.Add(Product.Create(Guid.NewGuid(),company,"PUB-1","Public Product",null,"APPAREL","PCS",DateTimeOffset.UtcNow).Value);ApiClient client=ApiClient.Create(clientId,"PARTNER_20","Partner 20",DateTimeOffset.UtcNow).Value;client.RotateCredential(Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(secret))).ToLowerInvariant(),null,1,DateTimeOffset.UtcNow);db.ApiClients.Add(client);db.ApplicationUsers.Add(ApplicationUser.Create(clientId,$"API_{clientId:N}","Partner principal",null,"API_CLIENT_NON_INTERACTIVE",DateTimeOffset.UtcNow).Value);db.ApiClientCompanies.Add(ApiClientCompany.Create(clientId,company));Guid permission=await db.Permissions.Where(x=>x.Code==SecurityPermissions.ClientCatalogRead).Select(x=>x.Id).SingleAsync(ct);db.ApiClientPermissions.Add(ApiClientPermission.Create(clientId,permission));await db.SaveChangesAsync(ct);}await using PostgreSqlCoreApiFactory factory=new(database.ConnectionString);using HttpClient http=factory.CreateClient();http.DefaultRequestHeaders.Authorization=new("ApiKey",$"{clientId}.{secret}");http.DefaultRequestHeaders.Add("X-Company-ID",company.ToString());using HttpResponseMessage catalog=await http.GetAsync("/api/v1/client/catalog/products?pageSize=999",ct);Assert.Equal(HttpStatusCode.OK,catalog.StatusCode);Assert.Contains("PUB-1",await catalog.Content.ReadAsStringAsync(ct),StringComparison.Ordinal);using HttpResponseMessage denied=await http.GetAsync($"/api/v1/client/orders/{Guid.NewGuid()}",ct);Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);http.DefaultRequestHeaders.Remove("X-Company-ID");http.DefaultRequestHeaders.Add("X-Company-ID",other.ToString());using HttpResponseMessage cross=await http.GetAsync("/api/v1/client/catalog/products",ct);Assert.Equal(HttpStatusCode.Forbidden,cross.StatusCode);string problem=await cross.Content.ReadAsStringAsync(ct);Assert.Contains("correlationId",problem,StringComparison.Ordinal);Assert.DoesNotContain("StackTrace",problem,StringComparison.OrdinalIgnoreCase);}
 [Fact]public async Task AnonymousClientMutationIsUnauthorizedAndVersionedRouteExists(){await using PostgreSqlCoreApiFactory factory=new(database.ConnectionString);using HttpClient http=factory.CreateClient();using HttpResponseMessage response=await http.PostAsync("/api/v1/client/orders/drafts",new StringContent("{}",Encoding.UTF8,"application/json"),TestContext.Current.CancellationToken);Assert.Equal(HttpStatusCode.Unauthorized,response.StatusCode);}
}
